<template>
  <div>
    <el-form :inline="true" :model="queryForm" size="small">
      <el-form-item>
        <el-select
          v-model="queryForm.source_id"
          placeholder="请选择设备"
          clearable
        >
          <el-option
            v-for="item in deviceList"
            :key="item.id"
            :label="item.source_name"
            :value="item.id"
          ></el-option>
        </el-select>
      </el-form-item>
      <el-form-item>
        <el-date-picker
          v-model="dateList"
          type="datetimerange"
          range-separator="至"
          start-placeholder="开始日期"
          end-placeholder="结束日期"
          value-format="yyyy-MM-dd HH:mm:ss"
        >
        </el-date-picker>
      </el-form-item>
      <el-form-item>
        <el-button type="primary" @click="query">查询</el-button>
        <el-button @click="reset">重置</el-button>
      </el-form-item>
    </el-form>
    <div v-if="recordsList.length > 0" class="recordsList">
      <div
        v-for="item in recordsList"
        :key="item.id"
        class="item"
        @click="detail(item)"
      >
        <div class="fs-12 flex-interval f-center mb-5" style="width: 100%">
          <el-popover
            placement="top"
            trigger="hover"
            :content="item.aiName"
            :disabled="item.aiName.length <= 8"
          >
            <div slot="reference" class="name">
              {{ item.aiName }}
            </div></el-popover
          >
          <div><i class="el-icon-time"></i>{{ item.time }}</div>
        </div>
        <el-image
          v-if="item.ai_file"
          class="aiimage"
          :src="item.ai_file"
          fit="fill"
          referrerpolicy="no-referrer"
        >
        </el-image>
        <span v-else>暂无图片</span>
      </div>
    </div>
    <el-empty description="暂无数据" v-else></el-empty>
    <pagination
      class="float-right mb-10"
      v-show="aiTotal > 0"
      :total="aiTotal"
      :page.sync="queryForm.page"
      :limit.sync="queryForm.size"
      @pagination="getDataList"
      layout="total, prev, pager, next"
      small
    />
    <el-dialog
      :visible.sync="dialogVisible"
      title="报警详情"
      width="50%"
      top="20px"
    >
      <el-form :model="form" label-width="80px" ref="formRef">
        <el-form-item label="事件名称" prop="ai_name">
          {{ form.aiName }}
        </el-form-item>
        <el-form-item label="报警时间" prop="ai_name">
          {{ form.time }}
        </el-form-item>
        <el-form-item label="报警图片" prop="ai_name">
          <el-image
            ref="imageRef"
            style="width: 500px; height: 300px"
            :src="form.ai_file"
            show-progress
            :preview-src-list="[form.ai_file]"
            fit="cover"
          />
        </el-form-item>
      </el-form>
      <el-table :data="form.ai_value">
        <el-table-column label="事件名称" align="center" prop="ai_name">
        </el-table-column>
        <el-table-column label="分析内容" align="center" prop="time">
          <template slot-scope="scope">
            <div
              v-for="(sitem, sindex) in scope.row.ai_class"
              :key="'detail_' + sindex"
              style="text-align: center"
            >
              {{ sitem.name }}: {{ sitem.confidence | toFixed }}
            </div>
          </template>
        </el-table-column>
      </el-table>
      <!-- <template #footer>
        <div class="dialog-footer">
          <el-button @click="dialogVisible = false">取消</el-button>
          <el-button type="primary" @click="onSubmit"> 确定 </el-button>
        </div>
      </template> -->
    </el-dialog>
  </div>
</template>

<script>
export default {
  data() {
    return {
      queryForm: {
        page: 1,
        size: 12,
        source_id: "",
      },
      dateList: [],
      recordsList: [],
      aiTotal: 0,
      dialogVisible: false,
      form: {},
      deviceList: [],
    };
  },
  created() {
    this.queryForm.source_id = Number(this.$route.query.source_id) || "";
    this.getDeviceList();
    this.getDataList();
  },
  filters: {
    toFixed(value) {
      return parseFloat(value).toFixed(2);
    },
  },
  methods: {
    getDeviceList() {
      this.$api
        .get(`/collect/getDataSourceList`, { params: { driver_protocol: 1 } })
        .then((res) => {
          if (res.data.data) {
            this.deviceList = res.data.data.filter(
              (item) => item.driver_protocol == 1
            );
            this.deviceList.unshift({
              id: "",
              source_name: "全部",
            });
          }
        });
    },
    //
    reset() {
      this.dateList = [];
      this.queryForm = {
        page: 1,
        size: 12,
        source_id: "",
      };
      this.getDataList();
    },
    query() {
      this.queryForm = {
        ...this.queryForm,
        page: 1,
        begin_time: this.dateList[0],
        end_time: this.dateList[1],
      };
      this.getDataList();
    },
    getDataList() {
      this.$api
        .get(`/ai/getDataAiRecordList`, {
          params: this.queryForm,
        })
        .then((res) => {
          if (res.data.data) {
            this.recordsList = res.data.data.map((item) => {
              return {
                ...item,
                ai_value: JSON.parse(item.ai_value),
                aiName: JSON.parse(item.ai_value)
                  .map((item) => item.ai_name)
                  .join(),
              };
            });
            this.aiTotal = res.data.total;
          } else {
            this.aiTotal = 0;
            this.recordsList = [];
          }
        });
    },
    detail(row) {
      this.form = { ...row };
      this.dialogVisible = true;
    },
  },
};
</script>

<style lang="scss" scoped>
.recordsList {
  display: flex;
  flex-wrap: wrap;
  .item {
    width: 22.5%;
    padding: 5px 15px;
    box-sizing: border-box;
    border: 1px solid #dcdfe6;
    cursor: pointer;
    margin-right: 34px;
    margin-bottom: 10px;
    color: #6a6a6a;
    background: #f7f7f7;

    ::v-deep .el-button {
      padding: 0 !important;
    }
    img {
      height: 120px;
      width: 100%;
    }
    .name {
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
      width: 100px;
    }
    @media (min-width: 1920px) {
      .name {
        width: 150px;
      }
    }
  }
  .item:nth-child(4n) {
    margin-right: 0;
  }
  .aiimage {
    height: 17vh;
    width: 100%;
  }
  @media (min-width: 1920px) {
    .aiimage {
      height: 19vh;
      width: 100%;
    }
  }
}
::v-deep .el-form-item {
  margin-bottom: 10px !important;
}
</style>
